CREATE TABLE "peran_kustom" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "peran_kustom_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"nama" varchar(50) NOT NULL,
	"peran_dasar" varchar(20) NOT NULL,
	"keterangan" varchar(150),
	"izin_tambah" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"izin_cabut" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"status_aktif" varchar(10) DEFAULT 'AKTIF' NOT NULL,
	"dibuat_pada" timestamp with time zone DEFAULT now() NOT NULL,
	"diubah_pada" timestamp with time zone,
	CONSTRAINT "peran_kustom_nama_key" UNIQUE("nama"),
	CONSTRAINT "chk_peran_kustom_dasar" CHECK (peran_dasar in ('STAF_PENJUALAN', 'KASIR', 'ADMIN', 'ADMIN_SISTEM', 'ADMIN_PERSEDIAAN', 'PETUGAS_GUDANG')),
	CONSTRAINT "chk_peran_kustom_status" CHECK (status_aktif in ('AKTIF','NONAKTIF'))
);
